import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
import { caretLeft, caretRight } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

const BREAKPOINT_CLASS = "hbr-css__chat-container";

/**
 * @since 1.1.41
 * @status beta
 *
 */
@Component({
	tag: "hbr-chat",
	styleUrl: "chat.scss",
	shadow: true,
})
export class HbrChat {
	private parentWindowRef: HTMLElement;
	private activeView: "sm" | "lg" = "lg";
	private collapsedOnResize = false;
	private mainRef: HTMLDivElement;

	/** Is the aside in collapsed state */
	@Prop({ reflect: true, mutable: true }) collapsed: boolean | null = null;

	/** the aside is collapsed */
	@Event({ eventName: "hbr-collapse" }) hbrCollapse: EventEmitter;

	/** the aside is expanded */
	@Event({ eventName: "hbr-expand" }) hbrExpand: EventEmitter;

	/** View changes between large (desktop) and small (mobile) */
	@Event({ eventName: "hbr-view-change" }) hbrViewChange: EventEmitter;

	@Element() host: HTMLHbrChatElement;
	@State() hasHeader = false;

	handleSlotChange() {
		this.hasHeader = hasSlot(this.host, "header");
	}

	handleResize(event) {
		const { activeBreakpoint } = event.detail;
		if (this.mainRef) {
			this.mainRef.classList.remove(`${BREAKPOINT_CLASS}-${this.activeView}`);
			this.mainRef.classList.add(`${BREAKPOINT_CLASS}-${activeBreakpoint}`);
		}
		if (activeBreakpoint !== this.activeView) {
			this.activeView = activeBreakpoint;
			if (this.activeView === "sm" && !this.collapsed) {
				this.collapsed = true;
				this.hbrCollapse.emit();
				this.collapsedOnResize = true;
			}
			if (this.activeView === "lg" && this.collapsedOnResize) {
				this.collapsed = false;
				this.hbrExpand.emit();
				this.collapsedOnResize = false;
			}
			this.hbrViewChange.emit({ view: this.activeView });
		}
	}

	handleCollapseClick() {
		this.collapsed = !this.collapsed;
		if (this.collapsed) {
			this.hbrCollapse.emit();
		} else {
			this.hbrExpand.emit();
		}
	}

	handleAsideClick() {
		if (this.activeView === "sm" && !this.collapsed) {
			this.collapsed = true;
			this.hbrCollapse.emit();
		}
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleResize = this.handleResize.bind(this);
		if (this.host?.closest) {
			this.parentWindowRef = this.host.closest("hbr-window");
		}
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host>
				<div
					class={{
						header: true,
						"header--empty": !this.hasHeader,
					}}
				>
					<slot name="header" onSlotchange={this.handleSlotChange} />
				</div>

				<div
					ref={(el) => {
						this.mainRef = el;
					}}
					class={{
						main: true,
						"header--empty": !this.hasHeader,
					}}
				>
					<slot name="main">
						<div
							class={{ aside: true, collapsed: !!this.collapsed }}
							onClick={this.handleAsideClick.bind(this)}
						>
							<div class={{ asideWrapper: true, collapsed: !!this.collapsed }}>
								<slot name="aside" />
							</div>
						</div>
						<div
							class={{
								"collapse-button-trigger": true,
								collapsed: !!this.collapsed,
							}}
						/>
						<div
							class={{
								"collapse-button-container": true,
								collapsed: !!this.collapsed,
							}}
						>
							<hbr-button
								part="collapse-button"
								variant="outline"
								circle
								sentiment="neutral"
								size="small"
								class="collapse-button"
								onClick={this.handleCollapseClick.bind(this)}
							>
								<hbr-icon
									asset={
										this.collapsed
											? customSystemIcons?.["caret-right"] || caretRight
											: customSystemIcons?.["caret-left"] || caretLeft
									}
									style={{ fontSize: "16px" }}
								/>
							</hbr-button>
						</div>
						<div class="chat-panel">
							<slot name="chat-panel" />
						</div>
					</slot>
				</div>

				<div class="footer">
					<slot name="footer" />
				</div>
				<hbr-resize-observer
				  debounce={100}
					breakpointClass={BREAKPOINT_CLASS}
					breakpoints={[768]}
					breakpointLabels={["sm", "lg"]}
					onHbr-resize={this.handleResize}
					responsive
					anchor={this.host}
					subscriber={this.parentWindowRef || this.host}
				/>
			</Host>
		);
	}
}
